/**
 * Stateless — plain data + lambdas, no ViewModel awareness, per this repo convention. Full screen,
 * not a bottom sheet (an eight-to-ten-preset live-preview picker plus "room to grow" wants a
 * screen, per the 2026-08-08 redesign-shell ADR). Owns its own `Scaffold`/`TopAppBar` with a back
 * button — same pattern as every other pushed (non-tab) destination in this app.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SettingsScreen(
    uiState: SettingsUiState,
    onThemeSelected: (MarketPulseTheme) -> Unit,
    onNavigateUp: () -> Unit,
    onMoreItemClick: (SettingsMoreItem) -> Unit
) {
    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(text = stringResource(id = R.string.settings_screen_title)) },
                navigationIcon = {
                    IconButton(onClick = onNavigateUp) {
                        Icon(
                            painter = painterResource(id = R.drawable.ic_back),
                            contentDescription = stringResource(id = R.string.nav_back_content_description)
                        )
                    }
                },
                // 💡 Matches the screen's background (and the same override every other pushed
                // destination's TopAppBar uses -- see NewsRoute.kt/AssetDetailRoute.kt) so the bar
                // doesn't render as a visibly different-colored band above the content. Left on the
                // default `colorScheme.surface` before, which reads noticeably different from
                // `colorScheme.background` now that light mode's background carries a per-preset
                // accent tint (`MarketPulseTheme.kt`'s `toColorScheme()`) that `surface` doesn't.
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.background
                )
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(dimensionResource(id = R.dimen.padding_large))
        ) {
            SettingsSectionHeader(text = stringResource(id = R.string.settings_section_theme))
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
            ThemePickerGrid(
                presets = uiState.availablePresets,
                selectedTheme = uiState.selectedTheme,
                onPresetSelected = onThemeSelected
            )

            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_xxlarge)))

            SettingsSectionHeader(text = stringResource(id = R.string.settings_section_more))
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_small)))
            SettingsMoreRow(
                label = stringResource(id = R.string.settings_item_notifications),
                onClick = { onMoreItemClick(SettingsMoreItem.NOTIFICATIONS) }
            )
            HorizontalDivider(color = MaterialTheme.colorScheme.outline)
            SettingsMoreRow(
                label = stringResource(id = R.string.settings_item_data_sync),
                onClick = { onMoreItemClick(SettingsMoreItem.DATA_SYNC) }
            )
            HorizontalDivider(color = MaterialTheme.colorScheme.outline)
            SettingsMoreRow(
                label = stringResource(id = R.string.settings_item_about),
                onClick = { onMoreItemClick(SettingsMoreItem.ABOUT) }
            )
            HorizontalDivider(color = MaterialTheme.colorScheme.outline)
        }
    }
}

/** The three "More" placeholder destinations. Per the spec: stubs only, tapping shows a Toast — do not build these sub-screens. */
enum class SettingsMoreItem { NOTIFICATIONS, DATA_SYNC, ABOUT }

@Composable
private fun SettingsSectionHeader(text: String) {
    Text(
        text = text,
        style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold),
        color = LocalPulseColors.current.accentPrimary
    )
}

@Composable
private fun SettingsMoreRow(label: String, onClick: () -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .padding(vertical = dimensionResource(id = R.dimen.padding_large)),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = label,
            style = MaterialTheme.typography.bodyLarge,
            color = MaterialTheme.colorScheme.onSurface
        )
        Icon(
            painter = painterResource(id = R.drawable.ic_chevron_forward),
            contentDescription = null,
            tint = LocalPulseColors.current.accentPrimary
        )
    }
}

